using System;using System.Windows;using System.Windows.Interop;using System.Runtime.InteropServices;
internal static class SuitePlacement {
 // Settings use available space instead of shrinking the widget and all page text.
 public static void PrepareWidget(Window widget){}
 internal static Rect Plan(Rect work,Rect widget){double width=Math.Min(widget.Width,Math.Max(1,work.Width-24)),height=Math.Min(460,Math.Max(1,work.Height-24));double top=widget.Top-12-height;double left=widget.Left;if(top<work.Top+12){top=work.Bottom-height-12;if(left-width-12>=work.Left+12)left-=width+12;}return new Rect(Math.Clamp(left,work.Left,Math.Max(work.Left,work.Right-width)),Math.Clamp(top,work.Top,Math.Max(work.Top,work.Bottom-height)),width,height);}
 public static void Above(Window widget,Window panel){var wh=new WindowInteropHelper(widget).Handle;var ph=new WindowInteropHelper(panel).EnsureHandle();if(!GetWindowRect(wh,out var r))return;var info=new Info{Size=Marshal.SizeOf<Info>()};if(!GetMonitorInfo(MonitorFromWindow(wh,2),ref info))return;var dpi=StickyNotes.DisplayDpi.Scale(widget);var plan=Plan(new Rect(info.Work.Left/dpi.DpiScaleX,info.Work.Top/dpi.DpiScaleY,(info.Work.Right-info.Work.Left)/dpi.DpiScaleX,(info.Work.Bottom-info.Work.Top)/dpi.DpiScaleY),new Rect(r.Left/dpi.DpiScaleX,r.Top/dpi.DpiScaleY,(r.Right-r.Left)/dpi.DpiScaleX,(r.Bottom-r.Top)/dpi.DpiScaleY));panel.Width=plan.Width;panel.Height=plan.Height;panel.UpdateLayout();SetWindowPos(ph,IntPtr.Zero,(int)Math.Round(plan.Left*dpi.DpiScaleX),(int)Math.Round(plan.Top*dpi.DpiScaleY),(int)Math.Round(plan.Width*dpi.DpiScaleX),(int)Math.Round(plan.Height*dpi.DpiScaleY),0x14);}
 public static bool IsAbove(Window widget,Window? panel){if(panel==null||!GetWindowRect(new WindowInteropHelper(widget).Handle,out var w)||!GetWindowRect(new WindowInteropHelper(panel).Handle,out var p))return false;var work=StickyNotes.NoteWindow.WorkArea(panel);var dpi=StickyNotes.DisplayDpi.Scale(panel);var bounds=new Rect(p.Left/dpi.DpiScaleX,p.Top/dpi.DpiScaleY,(p.Right-p.Left)/dpi.DpiScaleX,(p.Bottom-p.Top)/dpi.DpiScaleY);return bounds.Left>=work.Left-1&&bounds.Top>=work.Top-1&&bounds.Right<=work.Right+1&&bounds.Bottom<=work.Bottom+1&&Math.Abs((w.Right-w.Left)-(p.Right-p.Left))<=1;}
 [StructLayout(LayoutKind.Sequential)]struct RectNative{public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential)]struct Info{public int Size;public RectNative Monitor,Work;public uint Flags;}
 [DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr hwnd,out RectNative r);
 [DllImport("user32.dll")]static extern IntPtr MonitorFromWindow(IntPtr hwnd,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetMonitorInfo(IntPtr hwnd,ref Info info);
 [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr hwnd,IntPtr after,int x,int y,int width,int height,uint flags);
}
